CREATE INDEX IF NOT EXISTS ix_workspace_practice_config
    ON workspace (practice_config_id) WHERE practice_config_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_workspace_mentor_config
    ON workspace (mentor_config_id) WHERE mentor_config_id IS NOT NULL;

changeSet.sql:
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE llm_model_price ADD CONSTRAINT ex_llm_model_price_no_overlap
    EXCLUDE USING gist (
        model_id WITH =,
        tstzrange(effective_from, effective_to) WITH &&
    );
